package cinema.view.ui;
import cinema.model.*;
import java.awt.event.*;
import java.time.*;
import javax.swing.*;
import javax.swing.event.*;
/** Advisory preview of rows already loaded by the original screen; never queries or authorizes a save. */
public final class SchedulePreview {
    private SchedulePreview(){}
    public static JLabel create(JDialog dialog,JTable table,JComboBox<Phim> films,JComboBox<PhongChieu> rooms,JTextField day,JTextField time,SuatChieu existing){JLabel note=new JLabel();note.setBorder(BorderFactory.createEmptyBorder(Theme.s(Theme.MD),Theme.s(Theme.LG),Theme.s(Theme.MD),Theme.s(Theme.LG)));Runnable update=()->{try{Phim film=(Phim)films.getSelectedItem();PhongChieu room=(PhongChieu)rooms.getSelectedItem();if(film==null||room==null){note.setText("Chọn phim và phòng để xem thời gian dự kiến.");return;}LocalDateTime start=LocalDateTime.of(LocalDate.parse(day.getText().trim()),LocalTime.parse(time.getText().trim())),end=start.plusMinutes(film.thoiLuong()+room.thoiGianDonPhong());boolean overlap=false;for(int i=0;i<table.getModel().getRowCount();i++){var model=table.getModel();if(existing!=null&&Integer.valueOf(existing.maSuat()).equals(model.getValueAt(i,0)))continue;if(!room.tenPhong().equals(model.getValueAt(i,2))||"Đã hủy".equals(model.getValueAt(i,6)))continue;LocalDateTime otherStart=(LocalDateTime)model.getValueAt(i,3),otherEnd=(LocalDateTime)model.getValueAt(i,4);if(start.isBefore(otherEnd)&&end.isAfter(otherStart))overlap=true;}String text=overlap?"Có lịch đang hiển thị trùng phòng/giờ. Kiểm tra lại trước khi lưu.":"Trả phòng dự kiến: "+end+" · gồm "+room.thoiGianDonPhong()+" phút dọn. BUS kiểm tra lại toàn bộ khi lưu.";note.setText("<html><div style='width:440px'>"+text+"</div></html>");note.setForeground(overlap?Theme.danger():Theme.muted());note.setIcon(new Icons(overlap?"alert":"calendar"));}catch(java.time.format.DateTimeParseException e){note.setText("Chọn ngày/giờ hợp lệ để xem thời gian trả phòng dự kiến.");}};DocumentListener listener=new DocumentListener(){public void insertUpdate(DocumentEvent e){update.run();}public void removeUpdate(DocumentEvent e){update.run();}public void changedUpdate(DocumentEvent e){update.run();}};day.getDocument().addDocumentListener(listener);time.getDocument().addDocumentListener(listener);films.addActionListener(e->update.run());rooms.addActionListener(e->update.run());TableModelListener rows=e->update.run();table.getModel().addTableModelListener(rows);dialog.addWindowListener(new WindowAdapter(){public void windowClosed(WindowEvent e){table.getModel().removeTableModelListener(rows);}});update.run();return note;}
}
